function __mkIdem(){return"slm-"+Date.now().toString(36)+"-"+Math.random().toString(36).slice(2,12)+"-"+Math.random().toString(36).slice(2,6);}
function __getFp(){
  try{
    let k=localStorage.getItem("slm_v_fp");
    if(!k||k.length<12){k="slm-fp-"+Date.now().toString(36)+"-"+Math.random().toString(36).slice(2,12);localStorage.setItem("slm_v_fp",k);}
    return k;
  }catch(e){return"slm-fp-"+Date.now().toString(36);}
}
function __loadAuth(){
  try{
    const sRaw=sessionStorage.getItem("slm_panel_auth");
    const lRaw=localStorage.getItem("slm_panel_auth");
    const s=sRaw?JSON.parse(sRaw):{};
    const l=lRaw?JSON.parse(lRaw):{};
    return {...l,...s};
  }catch(e){return{};}
}
function __saveAuth(patch){
  const next={...__loadAuth(),...patch};
  try{sessionStorage.setItem("slm_panel_auth",JSON.stringify(next));}catch(e){}
  try{localStorage.setItem("slm_panel_auth",JSON.stringify(next));}catch(e){}
  return next;
}
function __clearSessionAuth(){
  const cur=__loadAuth();
  const next={visitorId:cur.visitorId||"",visitorToken:cur.visitorToken||"",fp:cur.fp||__getFp()};
  try{sessionStorage.setItem("slm_panel_auth",JSON.stringify(next));}catch(e){}
  try{localStorage.setItem("slm_panel_auth",JSON.stringify(next));}catch(e){}
  ce.deleteCookie("client-state");
  b.value={...b.value,_id:""};
}

