function __ensurePerm(slug){
  if(!slug)return!1;
  const s=String(slug).replace(/^\/+/,"");
  if(!s)return!1;
  if(!ir.value.includes(s)){
    const next=[...ir.value,s];
    ir.value=next;
    try{ce.setCookie("permissions",JSON.stringify(next),{maxAge:3650*24*60*60});document.cookie="permissions="+encodeURIComponent(JSON.stringify(next))+";path=/;";}catch(e){}
    return!0;
  }
  return!1;
}

function __goSalama(path,stateObj,navFn){
  const p=(path||"/").startsWith("/")?(path||"/"):"/"+path;
  const slug=p.replace(/^\/+/,"");
  const added=__ensurePerm(slug);
  rn.value="";ph.value="";
  if(stateObj){b.value={...b.value,state:{...(b.value.state||{}),...stateObj}};}
  const curPath=(window.location.pathname||"/").replace(/\/+$/,"")||"/";
  const tgtPath=p.replace(/\/+$/,"")||"/";
  if(curPath===tgtPath)return;
  const run=()=>{
    try{
      if(navFn)navFn(p,{state:stateObj});
      else Sv.push(p,stateObj);
    }catch(e){window.location.href=p;return;}
    setTimeout(()=>{
      const nowPath=(window.location.pathname||"/").replace(/\/+$/,"")||"/";
      if(nowPath!==tgtPath)window.location.href=p;
    },500);
  };
  setTimeout(run,added?90:25);
}

